537	        for (DBSObject o = object.getParentObject(); o != knownSubroot; o = o.getParentObject()) {
538	            if (o instanceof DBSStructContainer) {
539	                parts.addFirst(DBUtils.getQuotedIdentifier(o));
540	            }
541	        }
542	        return parts;
